import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useTeamContextValue } from '../../context'
import { TEAM_ACTION } from '../actions'

export const useRoles = () => {
  const [{
    roleListData,
    permissionListData,
    addRolePermissionsData,
    revokePermissionData,
    addGroupData,
    groupPermissionsData,
    groupUsersData,
    addUserToGroupData
  }, dispatch] = useTeamContextValue()

  const [callApi] = useServiceRequest(dispatch)

  const getRolesList = useCallback((payload = {}) => {
    callApi(TEAM_ACTION.getRolesList(payload))
  }, [callApi])

  const getPermissionList = useCallback((payload = {}) => {
    callApi(TEAM_ACTION.getPermissionList(payload))
  }, [callApi])

  const addRolePermissionsRequest = (payload = {}) => {
    callApi(TEAM_ACTION.addRolePermissions({ body: payload }))
  }

  const revokePermissionRequest = (payload = {}) => {
    callApi(TEAM_ACTION.revokePermission({ body: payload }))
  }

  const addGroupRequest = (payload = {}) => {
    callApi(TEAM_ACTION.addGroup({ body: payload }))
  }

  const getGroupPermissions = (payload = {}) => {
    callApi(TEAM_ACTION.getGroupPermissions({ query: payload }))
  }

  const getGroupUsers = (payload = {}) => {
    callApi(TEAM_ACTION.getGroupUsers({ query: payload }))
  }

  const addUserToGroupRequest = (payload = {}) => {
    callApi(TEAM_ACTION.addUserToGroup({ body: payload }))
  }

  const removeUserFromGroupRequest = (payload = {}) => {
    callApi(TEAM_ACTION.removeUserFromGroup({ body: payload }))
  }

  const resetState = (keys = []) => {
    dispatch(TEAM_ACTION.resetState(keys))
  }

  return {
    getRolesList,
    roleListData,
    getPermissionList,
    permissionListData,
    addRolePermissionsRequest,
    addRolePermissionsData,
    revokePermissionRequest,
    revokePermissionData,
    addGroupRequest,
    addGroupData,
    getGroupPermissions,
    groupPermissionsData,
    getGroupUsers,
    groupUsersData,
    addUserToGroupRequest,
    addUserToGroupData,
    removeUserFromGroupRequest,
    resetState
  }
}

export const useUserContext = () => {
  const [{ userListData, addUserData, updateUserStatusData, updateUserData, deleteUserData }, dispatch] = useTeamContextValue()

  const [callApi] = useServiceRequest(dispatch)

  const getUserList = (payload = {}) => {
    callApi(TEAM_ACTION.getUserList(payload))
  }

  const addUserRequest = (payload = {}) => {
    callApi(TEAM_ACTION.addUser({ body: payload }))
  }

  const updateUserStatusRequest = (payload = {}) => {
    callApi(TEAM_ACTION.updateUserStatus({ body: payload }))
  }

  const updateUserRequest = (payload = {}) => {
    callApi(TEAM_ACTION.updateUser({ body: payload }))
  }

  const deleteUserRequest = (payload = {}) => {
    callApi(TEAM_ACTION.deleteUser({ body: payload }))
  }

  const resetState = (keys = []) => {
    dispatch(TEAM_ACTION.resetState(keys))
  }

  return {
    getUserList,
    userListData,
    addUserRequest,
    addUserData,
    updateUserStatusRequest,
    updateUserStatusData,
    updateUserRequest,
    updateUserData,
    deleteUserRequest,
    deleteUserData,
    resetState
  }
}

export const usePermissionsContext = () => {
  const [{ addPermissionData }, dispatch] = useTeamContextValue()

  const [callApi] = useServiceRequest(dispatch)

  const addPermissionRequest = (payload = {}) => {
    callApi(TEAM_ACTION.addPermission({ body: payload }))
  }

  const resetState = (keys = []) => {
    dispatch(TEAM_ACTION.resetState(keys))
  }

  return {
    addPermissionRequest,
    addPermissionData,
    resetState
  }
}

export const useGlobalApisContext = () => {
  const [{ providerListData, agentProviderListData }, dispatch] = useTeamContextValue()

  const [callApi] = useServiceRequest(dispatch)

  const getAgentProviderList = (payload = {}) => {
    callApi(TEAM_ACTION.getAgentProviderList(payload))
  }

  const getProviderList = (payload = {}) => {
    callApi(TEAM_ACTION.getProviderList(payload))
  }

  return {
    getProviderList,
    providerListData,
    getAgentProviderList,
    agentProviderListData
  }
}
