/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import { Modal, Form, Select, Alert, message, Spin, Input } from 'antd'
import { useRoles } from '../../../state/hooks/useTeamContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { addGroupFormItemConfigs } from './utility'

const { Option } = Select

const AddGroupModal = ({ visible, form, toggleAddModal, ...props }) => {
  const { getFieldDecorator } = form
  const { getPermissionList, permissionListData, addGroupRequest, getRolesList, resetState } = useRoles()
  const [{ PERMISSION_LIST_ERROR, permissionListStatus, ADD_GROUP_ERROR, addGroupStatus, addGroupErrorData }] = useErrorContextValue()
  const [{ PERMISSION_LIST_LOADER, ADD_GROUP_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  const handleOk = () => {
    form.validateFields((err, values) => {
      if (!err) {
        addGroupRequest(values)
      }
    })
  }

  useEffect(() => {
    if (addGroupErrorData && addGroupErrorData.error) {
      const error = addGroupErrorData.error
      for (const key in error) {
        const values = form.getFieldsValue()
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [addGroupErrorData])

  useEffect(() => {
    if (addGroupStatus === 'success') {
      message.success('Group added successfully.')
      form.resetFields()
      toggleAddModal(false)
      getRolesList()
      resetState(['addGroupData'])
      resetError(['addGroupStatus'])
    }
  }, [addGroupStatus])

  useEffect(() => {
    getPermissionList()
  }, [])

  return (
    <Modal
      visible={visible}
      title='Add New Group'
      okText='Add'
      onCancel={() => toggleAddModal(false)}
      onOk={handleOk}
    >

      {(PERMISSION_LIST_ERROR) && <Alert type='error' message={permissionListStatus} banner />}
      {(ADD_GROUP_ERROR && !addGroupErrorData) && <Alert type='error' message={addGroupStatus} banner />}
      <Spin spinning={!!PERMISSION_LIST_LOADER || !!ADD_GROUP_LOADER}>
        <Form>
          <Form.Item
            label='Name'
            hasFeedback
          >
            {getFieldDecorator('name', addGroupFormItemConfigs.name)(
              <Input />
            )}
          </Form.Item>
          <Form.Item
            label='Permissions'
            hasFeedback
          >
            {
              getFieldDecorator(
                'permissions',
                addGroupFormItemConfigs.permissions
              )(
                <Select
                  mode='multiple'
                >
                  {
                    !PERMISSION_LIST_ERROR && Array.isArray(permissionListData)
                      ? (
                          permissionListData.map(permission => (
                            <Option key={permission.codename} value={permission.codename}>{permission.name}</Option>
                          ))
                        )
                      : null
                  }
                  {
                    // TODO: filter permissions that are already there or disable them maybe.
                  }
                </Select>
              )
            }
          </Form.Item>
        </Form>

      </Spin>
    </Modal>
  )
}
export default Form.create({ name: 'new-group' })(AddGroupModal)
