/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import { Button, Row, Col, Icon, Table, Spin, Empty, Input } from 'antd'
import { useHistory } from 'react-router'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { RowWithMargin } from '../../../../EmployeeBenefits/CommonComponents'
import { ColTextAlignRight } from '../../../../EmployeeBenefits/CommonComponents/index.style'
import { roleColumns } from './utility'
import { useRoles } from '../../../state/hooks/useTeamContext'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import AddGroupModal from './addGroup'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

const { Search } = Input

const Team = () => {
  const history = useHistory()
  const { getRolesList, roleListData } = useRoles()
  const [{ ROLE_LIST_LOADER }] = useLoaderContextValue()
  const [{ ROLE_LIST_ERROR }] = useErrorContextValue()
  const [addModalVisible, toggleAddModal] = useState(false)
  const [searchText, setSearchText] = useState(null)

  const getFilteredData = () => {
    if (searchText) {
      return roleListData.filter(role => new RegExp(searchText, 'i').test(role.name))
    }
    return roleListData
  }

  useEffect(() => {
    getRolesList()
  }, [])

  return (
    <EbEmptyPage
      history={history}
    >
      <RowWithMargin type='flex' justify='space-between'>
        <Col span={14}>
          <h2>Groups</h2>
        </Col>
        <Col span={6}>
          <Search
            placeholder='Search..'
            onChange={(e) => setSearchText(e.target.value)}
            disabled={!roleListData}
            allowClear
          />
        </Col>
        <PermissionCheckerV2 requiredPermission='ops.can_perform_team_actions'>
          <ColTextAlignRight span={4}>
            <Button
              type='primary'
              onClick={() => toggleAddModal(true)}
            >
              Add Group
              <Icon type='usergroup-add' />
            </Button>
          </ColTextAlignRight>
        </PermissionCheckerV2>
      </RowWithMargin>
      <Row>
        <Spin spinning={!!ROLE_LIST_LOADER}>
          {
            !ROLE_LIST_ERROR && Array.isArray(roleListData)
              ? (
                <Table
                  columns={roleColumns({ history })}
                  dataSource={getFilteredData()}
                  rowKey={rowData => rowData.name}
                />
                )
              : <Empty />
          }
        </Spin>
      </Row>
      <AddGroupModal
        visible={addModalVisible}
        toggleAddModal={toggleAddModal}
      />
    </EbEmptyPage>
  )
}
export default Team
